import{_ as t,o,c as a,a2 as d}from"./chunks/framework.BV2xZELn.js";const u=JSON.parse('{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"SECURITY.md","filePath":"SECURITY.md","lastUpdated":1791853050000}'),r={name:"SECURITY.md"};function s(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><h2 id="threat-model" tabindex="-1">Threat model <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;Threat model&quot;">​</a></h2><p>The web page is <strong>untrusted</strong>. It may be an attacker&#39;s page, a page that was compromised, or a third-party frame. The attacker can:</p><ul><li>run any JavaScript in the page and in any frame it can create;</li><li>send arbitrary messages on the bridge, with any content and size;</li><li>try to navigate the WebView to other origins or to local resources;</li><li>call plugins with malformed, oversized or hostile arguments, at high rates.</li></ul><p>The app, its native plugins and the OS are trusted. The attacker is not assumed to have a copy of the app, its keystore or device access.</p><h2 id="trust-boundary-and-controls" tabindex="-1">Trust boundary and controls <a class="header-anchor" href="#trust-boundary-and-controls" aria-label="Permalink to &quot;Trust boundary and controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Control</th><th>Finding</th></tr></thead><tbody><tr><td>Navigation</td><td><code>NavigationPolicy</code>: default deny for remote hosts; <code>about:blank</code> only for <code>about:</code>; <code>javascript:</code>, <code>file:</code>, <code>intent:</code>, <code>content:</code>, <code>data:</code> always blocked; plain <code>http</code> only in debugging; sub-frames checked too.</td><td>SEC-001</td></tr><tr><td>Frames</td><td>SDK is installed only in the top-level document (<code>window.top === window.self</code>).</td><td>SEC-001</td></tr><tr><td>Session token</td><td>Random token per page session, issued by <code>startSession</code> and embedded in the SDK. Every message must carry it (constant-time comparison). The token is invalidated when navigation starts. Requests and <code>bridge_ready</code> with a wrong or old token are ignored.</td><td>SEC-001, SEC-004</td></tr><tr><td>Stale responses</td><td>A response produced for a session that has ended is dropped; it is never sent into the next page.</td><td>BUG-003, SM-006</td></tr><tr><td>Message size</td><td>Messages above 2 MiB are rejected before JSON parsing.</td><td>SEC-004</td></tr><tr><td>Protocol</td><td>Strict validation of request, batch and option fields (<code>ProtocolException</code>). Identifiers are limited to <code>[A-Za-z0-9_-]</code> (1–128 chars); names to identifiers.</td><td>SEC-004, BUG-006</td></tr><tr><td>Errors</td><td>JS receives only protocol codes and a short message. Raw exception text and stack traces are logged natively and never sent. Plugins use <code>PluginException</code> for messages that are safe to show.</td><td>SEC-003, SM-010</td></tr><tr><td>Permissions</td><td>Checked before every call on the OS (<code>permission_handler</code>), with a 5 s cache so revocations are seen quickly. A denial returns <code>status</code> (<code>denied</code>, <code>permanentlyDenied</code>, <code>unsupported</code>) so JS can ask again or open settings. Unknown permissions are denied.</td><td>SEC-005, PERM-001</td></tr><tr><td>Storage paths</td><td><code>normalizeSandboxPath</code>: relative only, no <code>..</code> or <code>.</code>, no backslash, no NUL, no <code>:</code>, identifier-like segments, bounded length and depth. <code>resolveWithinRoot</code> resolves the nearest existing ancestor with <code>resolveSymbolicLinks</code> and rejects anything outside the sandbox root. Covered by a symlink test.</td><td>SEC-002</td></tr><tr><td>Storage sizes</td><td>5 MiB per file (read and write, measured on decoded bytes); 64 KiB per stored value; 128-char keys.</td><td>SEC-009</td></tr><tr><td>Rate limiting</td><td>Sliding window per <code>plugin.method</code>, applied only after the plugin resolves. At most 1024 tracked keys, idle keys pruned. <code>camera.takePhoto</code> 3/s, <code>geolocation.getCurrentPosition</code> 5/s, all other methods 50/s.</td><td>SEC-008</td></tr><tr><td>Concurrency</td><td><code>maxConcurrentCalls</code> per plugin is enforced; camera is 1. Duplicate in-flight request ids are rejected.</td><td>CONC-001, CONC-002</td></tr><tr><td>Timeouts</td><td>Every execution has a timeout from configuration (30 s default). Batches have an overall timeout.</td><td>SM-004, BUG-002, BUG-013</td></tr><tr><td>Debug tooling</td><td>The inspector UI is only shown when <code>kDebugMode</code> is true, and it redacts <code>args</code> and <code>data</code> before storing them.</td><td>SEC-007</td></tr><tr><td>Release signing</td><td>Release builds use a keystore from environment variables. Without one the release APK is unsigned; the debug key is never used.</td><td>SEC-006</td></tr><tr><td>Android manifest</td><td>Only the permissions the plugins need: <code>CAMERA</code>, <code>ACCESS_FINE_LOCATION</code>, <code>ACCESS_COARSE_LOCATION</code>.</td><td>BUG-010</td></tr><tr><td>iOS</td><td>Usage strings are present for camera, microphone, photo library and location.</td><td>BUG-010</td></tr></tbody></table><h2 id="storage-and-cache-integrity" tabindex="-1">Storage and cache integrity <a class="header-anchor" href="#storage-and-cache-integrity" aria-label="Permalink to &quot;Storage and cache integrity&quot;">​</a></h2><p>Cached results are only returned for methods listed in <code>cacheableMethods</code> (read-only). Writes always run. A successful write invalidates the plugin&#39;s cache entries, so a read that follows a write is never stale (BUG-001, SM-003).</p><h2 id="known-limitations-accepted" tabindex="-1">Known limitations (accepted) <a class="header-anchor" href="#known-limitations-accepted" aria-label="Permalink to &quot;Known limitations (accepted)&quot;">​</a></h2><ul><li><strong>SEC-010 — camera paths.</strong> Picker results are absolute paths in the application&#39;s temporary directory. JavaScript needs them to show or upload the files. The app does not give JavaScript access to arbitrary paths: the camera plugin only returns paths the picker produced.</li><li><strong>Parallel batches and <code>stopOnError</code>.</strong> Calls in a parallel batch start together, so <code>stopOnError</code> only applies to sequential batches (BUG-007). This is documented in the API, and sequential mode marks skipped items as <code>CANCELLED</code> with <code>Not executed</code>.</li><li><strong>Origin of the page.</strong> The bridge trusts any top-level document loaded from an allow-listed host. Hosts are configured in code (<code>WebViewHostConfig</code>); the default is an empty allow-list, so the app only shows its own HTML.</li><li><strong>Token scope.</strong> The token protects against other frames and stale pages. It does not authenticate a compromised allow-listed host.</li><li><strong>Rate limits are per process.</strong> They reset when the app restarts.</li><li><strong>iOS.</strong> Permission checks and usage strings are in place. The iOS project is built without code signing in CI (IOS-001), but the app is not run on a simulator or device, so iOS runtime permission behaviour is not tested.</li></ul><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>Report security issues to the repository owner privately. Do not open a public issue with exploit details.</p>',13)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
